// ---------------- Navigation ----------------
function goTo(id){
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  const map = {
    welcome:'screen-welcome',
    suitcaseIntro:'screen-suitcase-intro',
    story:'screen-story',
    moduleA:'screen-moduleA',
    moduleB:'screen-moduleB',
    moduleC:'screen-moduleC',
    moduleD:'screen-moduleD',
    end:'screen-end',
  };
  document.getElementById(map[id]).classList.add('active');
  window.scrollTo(0,0);

  if(id==='story') renderStory();
  if(id==='moduleA') renderModuleA();
  if(id==='moduleB') renderModuleB();
  if(id==='moduleC') renderModuleC();
  if(id==='moduleD') renderModuleD();
  if(id==='end') renderEnd();
}

function selectGender(g){
  state.gender = g;
  document.querySelectorAll('.avatar-choice').forEach(el=>el.classList.remove('selected'));
  document.querySelector(`.avatar-choice[data-gender="${g}"]`).classList.add('selected');
  checkStartEnabled();
}
document.getElementById('input-name').addEventListener('input', checkStartEnabled);
function checkStartEnabled(){
  const name = document.getElementById('input-name').value.trim();
  document.getElementById('btn-start').disabled = !(name.length>0 && state.gender);
}

function startJourney(){
  state.name = document.getElementById('input-name').value.trim();
  document.getElementById('topbar').style.display='flex';
  document.getElementById('suitcase-img').src = IMAGES.suitcase3d;
  updateTopbar();
  const title = state.gender==='boy' ? `أهلًا يا بطل ${state.name}!` : `أهلًا يا بطلة ${state.name}!`;
  document.getElementById('suitcase-intro-title').innerText = title;
  goTo('suitcaseIntro');
}

function updateTopbar(){
  document.getElementById('star-count').innerText = state.stars + ' ⭐';
  const totalCycles = CYCLES.length;
  let progressUnits = totalCycles*2; // A + C per cycle
  let done = state.cycleIndex*2 + (state._inC?1:0);
  let pct = Math.min(100, Math.round((state.stars/( (CYCLES.length*5) + (CYCLES.length) + D_QUESTIONS.length ))*100));
  document.getElementById('progress-fill').style.width = pct+'%';
}

function addStar(fromEl){
  state.stars++;
  updateTopbar();
  flyStar(fromEl);
}

function flyStar(fromEl){
  const target = document.getElementById('suitcase-wrap');
  if(!fromEl || !target) return;
  const s = document.createElement('img');
  s.src = IMAGES.star;
  s.className='star-fly';
  const r1 = fromEl.getBoundingClientRect();
  const r2 = target.getBoundingClientRect();
  s.style.left = (r1.left + r1.width/2 - 13)+'px';
  s.style.top = (r1.top + r1.height/2 - 13)+'px';
  document.body.appendChild(s);
  requestAnimationFrame(()=>{
    s.style.left = (r2.left + r2.width/2 - 13)+'px';
    s.style.top = (r2.top + r2.height/2 - 13)+'px';
    s.style.transform='scale(0.4)';
    s.style.opacity='0.6';
  });
  setTimeout(()=>s.remove(), 850);
}

// ---------------- Story ----------------
function renderStory(){
  const c = CYCLES[state.cycleIndex];
  document.getElementById('story-img').src = IMAGES[c.storyImg];
  document.getElementById('story-title').innerText = c.storyTitle;
  document.getElementById('story-text').innerText = c.storyText;
}

// ---------------- Module A: order ayat ----------------
let moduleA_state = { slots:[], shuffled:[], used:[] };

function renderModuleA(){
  const c = CYCLES[state.cycleIndex];
  document.getElementById('anchor-ayah').innerText = c.anchor.text;
  moduleA_state.slots = new Array(c.order.length).fill(null);
  moduleA_state.used = new Array(c.order.length).fill(false);
  moduleA_state.shuffled = c.order.map((t,i)=>({t,i})).sort(()=>Math.random()-0.5);
  document.getElementById('moduleA-check').style.display='block';
  document.getElementById('moduleA-next').style.display='none';
  document.getElementById('moduleA-feedback').innerText='';
  renderChips();
  renderSlots();
}
function renderChips(){
  const wrap = document.getElementById('ayat-chips');
  wrap.innerHTML='';
  moduleA_state.shuffled.forEach((item, idx)=>{
    const chip = document.createElement('div');
    chip.className='chip'+(moduleA_state.used[idx]?' used':'');
    chip.innerText = item.t;
    chip.onclick = ()=>placeChip(idx);
    wrap.appendChild(chip);
  });
}
function renderSlots(){
  const wrap = document.getElementById('ayat-slots');
  wrap.innerHTML='';
  moduleA_state.slots.forEach((val, i)=>{
    const slot = document.createElement('div');
    slot.className='slot';
    slot.innerHTML = `<div class="num">${i+1}</div><div>${val ? val.t : ''}</div>`;
    slot.onclick = ()=>{ if(val){ removeSlot(i);} };
    wrap.appendChild(slot);
  });
}
function placeChip(idx){
  const emptySlot = moduleA_state.slots.findIndex(s=>s===null);
  if(emptySlot===-1) return;
  moduleA_state.slots[emptySlot] = moduleA_state.shuffled[idx];
  moduleA_state.used[idx]=true;
  renderChips();
  renderSlots();
}
function removeSlot(i){
  const item = moduleA_state.slots[i];
  const idx = moduleA_state.shuffled.findIndex(s=>s.i===item.i);
  moduleA_state.used[idx]=false;
  moduleA_state.slots[i]=null;
  renderChips();
  renderSlots();
}
function resetModuleA(){ renderModuleA(); }
function checkModuleA(){
  const c = CYCLES[state.cycleIndex];
  if(moduleA_state.slots.includes(null)){
    document.getElementById('moduleA-feedback').innerText='رتّب كل الآيات أولًا 🙂';
    document.getElementById('moduleA-feedback').className='feedback bad';
    return;
  }
  let allCorrect = true;
  const slotsEls = document.querySelectorAll('#ayat-slots .slot');
  moduleA_state.slots.forEach((item,i)=>{
    const ok = item.i === i;
    if(!ok) allCorrect=false;
    slotsEls[i].classList.add(ok?'correct':'wrong');
  });
  if(allCorrect){
    document.getElementById('moduleA-feedback').innerText='أحسنت! ترتيب صحيح 🎉';
    document.getElementById('moduleA-feedback').className='feedback';
    for(let i=0;i<c.order.length;i++){
      addStar(slotsEls[i]);
    }
    document.getElementById('moduleA-check').style.display='none';
    document.getElementById('moduleA-next').style.display='block';
  } else {
    document.getElementById('moduleA-feedback').innerText='قريب! جرّب مرة أخرى 💪';
    document.getElementById('moduleA-feedback').className='feedback bad';
  }
}

// ---------------- Module B: mini game ----------------
let mg = { running:false, score:0, items:[], raf:null, timer:null };
function renderModuleB(){
  const g = MINIGAMES[state.cycleIndex % MINIGAMES.length];
  document.getElementById('minigame-title').innerText = g.title;
  document.getElementById('minigame-desc').innerText = g.desc;
  document.getElementById('minigame-start').style.display='block';
  document.getElementById('minigame-next').style.display='none';
  document.getElementById('minigame-score').innerText='0';
  const canvas = document.getElementById('minigame-canvas');
  canvas.width = canvas.clientWidth;
  canvas.height = canvas.clientHeight;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0,0,canvas.width,canvas.height);
}
function startMiniGame(){
  const canvas = document.getElementById('minigame-canvas');
  canvas.width = canvas.clientWidth;
  canvas.height = canvas.clientHeight;
  const ctx = canvas.getContext('2d');
  mg.running=true; mg.score=0; mg.items=[];
  document.getElementById('minigame-start').style.display='none';
  document.getElementById('minigame-score').innerText='0';

  const starImg = new Image();
  starImg.src = IMAGES.star;

  function spawn(){
    if(!mg.running) return;
    mg.items.push({
      x: Math.random()*(canvas.width-36)+18,
      y: -30,
      speed: 1.4 + Math.random()*1.6,
      size: 34,
      caught:false
    });
  }
  let spawnTimer = setInterval(spawn, 550);

  function loop(){
    if(!mg.running) return;
    ctx.clearRect(0,0,canvas.width,canvas.height);
    mg.items.forEach(it=>{
      if(it.caught) return;
      it.y += it.speed;
      ctx.drawImage(starImg, it.x-it.size/2, it.y-it.size/2, it.size, it.size);
    });
    mg.items = mg.items.filter(it=> it.y < canvas.height+40 && !it.caught);
    mg.raf = requestAnimationFrame(loop);
  }
  loop();

  function handleTap(e){
    const rect = canvas.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    const x = clientX-rect.left, y = clientY-rect.top;
    mg.items.forEach(it=>{
      if(it.caught) return;
      const d = Math.hypot(it.x-x, it.y-y);
      if(d < it.size){
        it.caught=true;
        mg.score++;
        document.getElementById('minigame-score').innerText = mg.score;
      }
    });
  }
  canvas.onclick = handleTap;
  canvas.ontouchstart = function(e){ e.preventDefault(); handleTap(e); };

  mg.timer = setTimeout(()=>{
    mg.running=false;
    clearInterval(spawnTimer);
    cancelAnimationFrame(mg.raf);
    document.getElementById('minigame-next').style.display='block';
  }, 10000);
}

// ---------------- Module C: guess image ----------------
let moduleC_state = { answered:false, hintUsed:false };
function renderModuleC(){
  const c = CYCLES[state.cycleIndex].moduleC;
  moduleC_state = { answered:false, hintUsed:false };
  document.getElementById('moduleC-verse').innerText = c.verse;
  document.getElementById('moduleC-feedback').innerText='';
  document.getElementById('moduleC-next').style.display='none';
  document.getElementById('moduleC-hint').style.display='block';
  document.getElementById('moduleC-images-card').style.display='block';
  document.getElementById('moduleC-words-card').style.display='none';

  const options = [c.correctImg, ...c.distractors].sort(()=>Math.random()-0.5);
  const wrap = document.getElementById('moduleC-images');
  wrap.innerHTML='';
  options.forEach(key=>{
    const div = document.createElement('div');
    div.className='img-choice';
    div.innerHTML = `<img src="${IMAGES[key]}">`;
    div.onclick = ()=>answerModuleC(key===c.correctImg, div);
    wrap.appendChild(div);
  });
}
function showHint(){
  const c = CYCLES[state.cycleIndex].moduleC;
  moduleC_state.hintUsed = true;
  document.getElementById('moduleC-images-card').style.display='none';
  document.getElementById('moduleC-words-card').style.display='block';
  document.getElementById('moduleC-hint').style.display='none';
  const words = [c.keyword, ...c.wordDistractors].sort(()=>Math.random()-0.5);
  const wrap = document.getElementById('moduleC-words');
  wrap.innerHTML='';
  words.forEach(w=>{
    const div = document.createElement('div');
    div.className='word-choice';
    div.innerText=w;
    div.onclick=()=>answerModuleC(w===c.keyword, div);
    wrap.appendChild(div);
  });
}
function answerModuleC(correct, el){
  if(moduleC_state.answered) return;
  if(correct){
    moduleC_state.answered = true;
    el.classList.add('correct');
    document.getElementById('moduleC-feedback').innerText='أحسنت! إجابة صحيحة 🎉';
    document.getElementById('moduleC-feedback').className='feedback';
    document.getElementById('moduleC-hint').style.display='none';
    document.getElementById('moduleC-next').style.display='block';
    addStar(el);
  } else {
    el.classList.add('wrong');
    document.getElementById('moduleC-feedback').innerText='حاول مرة أخرى 💪';
    document.getElementById('moduleC-feedback').className='feedback bad';
  }
}
function nextAfterC(){
  state.cycleIndex++;
  if(state.cycleIndex < CYCLES.length){
    goTo('story');
  } else {
    state.dQuestionIndex = 0;
    state.dScore = 0;
    goTo('moduleD');
  }
}
function goToAfterB(){
  const c = CYCLES[state.cycleIndex];
  if(c.moduleC){
    goTo('moduleC');
  } else {
    nextAfterC();
  }
}

// ---------------- Module D: final MCQ ----------------
function renderModuleD(){
  const total = D_QUESTIONS.length;
  document.getElementById('moduleD-progress').innerText = `سؤال ${state.dQuestionIndex+1} من ${total}`;
  const q = D_QUESTIONS[state.dQuestionIndex];
  document.getElementById('moduleD-question').innerText = q.q;
  document.getElementById('moduleD-feedback').innerText='';
  document.getElementById('moduleD-next').style.display='none';
  const wrap = document.getElementById('moduleD-options');
  wrap.innerHTML='';
  q.options.forEach((opt,i)=>{
    const div = document.createElement('div');
    div.className='mcq-opt';
    div.innerText=opt;
    div.onclick = ()=>answerD(i===q.correct, div);
    wrap.appendChild(div);
  });
}
let dAnswered=false;
function answerD(correct, el){
  if(dAnswered) return;
  dAnswered=true;
  if(correct){
    el.classList.add('correct');
    document.getElementById('moduleD-feedback').innerText='إجابة صحيحة! 🌟';
    document.getElementById('moduleD-feedback').className='feedback';
    addStar(el);
    state.dScore++;
  } else {
    el.classList.add('wrong');
    document.getElementById('moduleD-feedback').innerText='إجابة خاطئة، لا بأس! 🙂';
    document.getElementById('moduleD-feedback').className='feedback bad';
  }
  document.getElementById('moduleD-next').style.display='block';
}
function nextD(){
  dAnswered=false;
  state.dQuestionIndex++;
  if(state.dQuestionIndex < D_QUESTIONS.length){
    renderModuleD();
  } else {
    goTo('end');
  }
}

// ---------------- End screen ----------------
function renderEnd(){
  const title = state.gender==='boy' ? `مبارك يا بطل ${state.name}! 🎉` : `مبارك يا بطلة ${state.name}! 🎉`;
  document.getElementById('end-title').innerText = title;
  document.getElementById('end-avatar').src = IMAGES[state.gender];
  document.getElementById('end-text').innerText = `لقد جمعت ${state.stars} نجمة من الأعمال الصالحة، وامتلأت حقيبتك. أحسنت صنعًا!`;
  document.getElementById('end-badge').innerText = `⭐ ${state.stars} نجمة`;
  // close suitcase animation
  const suitcase = document.getElementById('end-suitcase');
  suitcase.style.transition='transform .6s ease';
  setTimeout(()=>{ suitcase.style.transform='scale(1.15) rotate(-3deg)'; }, 400);
  launchConfetti();
}

function launchConfetti(){
  const colors = ['#F4A93B','#2F9E7A','#F2765C','#4FB3E8'];
  for(let i=0;i<26;i++){
    const el = document.createElement('div');
    el.style.position='fixed';
    el.style.width='10px'; el.style.height='10px';
    el.style.background = colors[i%colors.length];
    el.style.left = Math.random()*100+'vw';
    el.style.top='-10px';
    el.style.borderRadius='3px';
    el.style.zIndex=997;
    el.style.transition='transform 2.2s ease-in, opacity 2.2s ease-in';
    document.body.appendChild(el);
    requestAnimationFrame(()=>{
      el.style.transform=`translateY(${100+Math.random()*20}vh) rotate(${Math.random()*400}deg)`;
      el.style.opacity='0.15';
    });
    setTimeout(()=>el.remove(), 2300);
  }
}